from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrdrxParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        if self.mo_num == '0':
            self.set_parameter('drxInactivityTimer', '0ms')
            self.set_parameter('drxLongCycle', '10ms')
            self.set_parameter('drxOnDurationTimer', '1ms')
            self.set_parameter('drxPriority', '0')
            self.set_parameter('drxRetransTimerUl', '0slot')
            self.set_parameter('userLabel', 'NoDRX')
        elif self.mo_num == '1':
            self.set_parameter('drxPriority', '32')
            self.set_parameter('drxRetransTimerUl', '0slot')
            self.set_parameter('userLabel', 'Default NonGbr')
        elif self.mo_num == '2':
            self.set_parameter('drxInactivityTimer', '20ms')
            self.set_parameter('drxLongCycle', '40ms')
            self.set_parameter('drxPriority', '1')
            self.set_parameter('drxRetransTimerUl', '0slot')
            self.set_parameter('userLabel', 'Default VoNR')
        elif self.mo_num == '3':
            self.set_parameter('drxInactivityTimer', '10ms')
            self.set_parameter('drxLongCycle', '640ms')
            self.set_parameter('drxPriority', '16')
            self.set_parameter('drxRetransTimerUl', '0slot')
            self.set_parameter('userLabel', 'Default ANR')
        elif self.mo_num == '4':
            self.set_parameter('drxInactivityTimer', '40ms')
            self.set_parameter('drxLongCycle', '40ms')
            self.set_parameter('drxOnDurationTimer', '6ms')
            self.set_parameter('drxPriority', '90')
            self.set_parameter('drxRetransTimerUl', '0slot')
            self.set_parameter('userLabel', 'NonGbr')

        if self.is_sa:
            if self.mo_num == '4':
                self.set_parameter('drxInactivityTimer', '20ms')
                self.set_parameter('drxLongCycle', '40ms')
                self.set_parameter('drxOnDurationTimer', '10ms')
                self.set_parameter('drxPriority', '90')
                self.set_parameter('drxRetransTimerDl', '16slot')
                self.set_parameter('drxRetransTimerUl', '16slot')
                self.set_parameter('userLabel', 'NonGbr')
            if self.mo_num == '5':
                self.set_parameter('drxInactivityTimer', '80ms')
                self.set_parameter('drxLongCycle', '320ms')
                self.set_parameter('drxOnDurationTimer', '20ms')
                self.set_parameter('drxPriority', '50')
                self.set_parameter('drxRetransTimerDl', '0slot')
                self.set_parameter('drxRetransTimerUl', '0slot')
                self.set_parameter('userLabel', 'ANR')
            if self.mo_num == '6':
                self.set_parameter('drxInactivityTimer', '20ms')
                self.set_parameter('drxLongCycle', '40ms')
                self.set_parameter('drxOnDurationTimer', '10ms')
                self.set_parameter('drxPriority', '1')
                self.set_parameter('drxRetransTimerDl', '0slot')
                self.set_parameter('drxRetransTimerUl', '0slot')
                self.set_parameter('userLabel', 'Default VoNR')
